"""Render a self-contained report for the actual workflow tag, never another experiment."""
import argparse,html,json
from mtr_project.paths import ROOT
from mtr_project.workflow import SPLITS,expected_records,collect_outputs,validate_tag


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--tag',required=True);args=p.parse_args();validate_tag(args.tag)
    config=json.loads((ROOT/'config/project-v2-scenes.json').read_text());expected=expected_records(config,args.tag)
    collect_outputs(ROOT,args.tag,expected)
    base=ROOT/'runs/project-v2'/args.tag;sections=[]
    for split in SPLITS:
        report=json.loads((base/f'{split}-evaluation.json').read_text());s=report['summary'];coverage=[];windows=[];errors=[]
        for instruction,value in s['by_diagnostic_instruction'].items():
            coverage.append(f'<tr><td>{html.escape(instruction)}</td><td>{value["selected"]}/{value["windows"]}</td></tr>')
        for r in report['windows']:
            choices=[c['instruction']+' → '+str(c['selected_candidate']) for c in r['diagnostic_choices'] if c['selected_candidate'] is not None]
            windows.append(f'<tr><td>{html.escape(r["scene"]["key"])}</td><td>{r["passing_count"]}/{r["candidate_count"]}</td><td>{html.escape("; ".join(choices) or "\u6ca1\u6709\u5339\u914d\u5019\u9009")}</td></tr>')
        for name,value in s['baseline_errors'].items():
            errors.append(f'<tr><td>{html.escape(name)}</td><td><code>{html.escape(json.dumps(value))}</code></td></tr>')
        sections.append(f'<section><h2>{split}</h2><p>{s["recordings"]} \u6bb5\u8bb0\u5f55 · {s["windows"]} \u4e2a\u7a97\u53e3 · {s["passing_candidates"]}/{s["total_candidates"]} \u6761\u5019\u9009\u901a\u8fc7\u6709\u9650\u68c0\u67e5</p><h3>\u8bca\u65ad\u6307\u4ee4\u8986\u76d6</h3><table><tr><th>\u6307\u4ee4</th><th>\u627e\u5230\u5019\u9009\u7684\u7a97\u53e3</th></tr>'+''.join(coverage)+'</table><h3>\u6bcf\u4e2a\u7a97\u53e3</h3><table><tr><th>\u7a97\u53e3</th><th>\u901a\u8fc7\u68c0\u67e5</th><th>\u52a8\u4f5c → \u5019\u9009\u7f16\u53f7</th></tr>'+''.join(windows)+'</table><h3>\u4e0e\u5df2\u8bb0\u5f55\u672a\u6765\u7684\u5e73\u5747\u4f4d\u7f6e\u8bef\u5dee ADE（\u7c73）</h3><p>\u540c\u65f6\u770b\u4e0a\u9762\u7684\u8986\u76d6\u7387；\u9009\u62e9\u5931\u8d25\u7684\u7a97\u53e3\u6ca1\u6709\u88ab\u9009\u8def\u5f84\u8bef\u5dee。oracle \u4f7f\u7528\u672a\u6765，\u53ea\u662f\u5bf9\u7167\u4e0a\u754c，\u4e0d\u80fd\u7528\u4e8e\u5b9e\u9645\u9009\u8def。</p><table><tr><th>\u5bf9\u7167</th><th>\u7edf\u8ba1</th></tr>'+''.join(errors)+f'</table><p>\u5b8c\u6574\u7ed3\u679c：<a href="../{split}-evaluation.json">{split}-evaluation.json</a></p></section>')
    document='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ECE191 \u5b8c\u6574\u6d41\u7a0b\u7ed3\u679c</title><style>body{max-width:1050px;margin:36px auto;padding:0 22px;font:16px/1.7 system-ui;color:#243b50}h1,h2{color:#147e83}section{margin:40px 0}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:8px;text-align:left;border-bottom:1px solid #dce3e8;overflow-wrap:anywhere}aside{background:#fff4e5;padding:18px;border-left:4px solid #d79548}code{overflow-wrap:anywhere}</style><h1>ECE191 · \u5b8c\u6574\u79bb\u7ebf\u6d41\u7a0b</h1><p>\u5b9e\u9a8c\u6807\u7b7e：<strong>'''+html.escape(args.tag)+'''</strong></p><p>\u6570\u636e\u68c0\u67e5 → \u73af\u5883\u68c0\u67e5 → \u8f6c\u6362/\u6a21\u578b/\u7b5b\u9009（\u53ef\u590d\u7528\u7f13\u5b58）→ \u8bc4\u4ef7 → \u672c\u62a5\u544a</p><aside>\u8fd9\u91cc\u7684\u6307\u4ee4\u662f\u56fa\u5b9a\u8bca\u65ad\u6307\u4ee4，\u672a\u88ab\u5f53\u4f5c\u8fd9\u4e9b\u7a97\u53e3\u7684\u771f\u5b9e\u8bed\u8a00\u6807\u7b7e。\u5019\u9009\u8986\u76d6\u4e0e\u56de\u653e\u8bef\u5dee\u4e0d\u7b49\u4e8e\u8bed\u8a00\u51c6\u786e\u7387\u6216\u5b9e\u9645\u9a7e\u9a76\u6210\u529f。\u539f\u59cb\u6a21\u578b、\u5e73\u6ed1\u8def\u5f84\u4e0e\u8bed\u8a00\u9009\u62e9\u5206\u522b\u4fdd\u5b58；\u6ca1\u6709\u8bad\u7ec3\u6216\u63a7\u5236\u8f66\u8f86。</aside>'''+''.join(sections)+'''<h2>\u590d\u73b0\u4e0e\u65e5\u5fd7</h2><p>\u5728 Ubuntu \u9879\u76ee\u76ee\u5f55\u6267\u884c <code>bash run_wsl.sh run_offline_project.py --tag '''+html.escape(args.tag)+'''</code>。\u9ed8\u8ba4\u53ea\u5141\u8bb8\u590d\u7528\u5df2\u6709\u6a21\u578b\u6d41\u6c34\u7ebf\u7ed3\u679c；\u7f3a\u5c11\u6b65\u9aa4\u4f1a\u505c\u6b62。\u5f00\u542f\u65b0\u8ba1\u7b97\u9700\u6dfb\u52a0 <code>--compute-missing</code>。</p><p>\u672c\u6b21\u662f\u5426\u6267\u884c\u65b0\u8ba1\u7b97，\u4ee5\u540c\u6807\u7b7e <code>workflows/\u65f6\u95f4\u6233/workflow.json</code> \u4e2d\u7684 <code>pipeline_execution</code> \u4e3a\u51c6。\u65e7\u7f13\u5b58\u6ca1\u6709\u5386\u53f2\u8f93\u51fa\u6307\u7eb9\u65f6\u4f1a\u660e\u786e\u8ba1\u6570；\u672c\u6b21\u53e6\u5916\u4fdd\u5b58\u5f53\u524d\u5168\u90e8\u8f93\u5165\u8f93\u51fa\u6307\u7eb9，\u4e0d\u80fd\u5012\u63a8\u5386\u53f2\u6587\u4ef6\u672a\u66fe\u53d8\u5316。</p><p>\u8fd9\u662f\u672c\u673a\u91cd\u590d\u8fd0\u884c\u5165\u53e3，\u4e0d\u662f\u5e72\u51c0\u673a\u5668\u5b89\u88c5\u8bc1\u660e。\u5148\u786e\u8ba4 workflow.json \u7684\u5b8c\u6210\u72b6\u6001；\u5355\u72ec\u751f\u6210\u672c\u9875\u9762\u5e76\u4e0d\u80fd\u8bc1\u660e\u6574\u5957\u6d41\u7a0b\u6210\u529f。</p></html>'''
    dest=base/'report';dest.mkdir(exist_ok=True);(dest/'index.html').write_text(document,encoding='utf-8');print(dest/'index.html')


if __name__=='__main__':main()
